import { Injectable } from '@angular/core';
import { HttpInterceptor, HttpRequest, HttpHandler, HttpEvent } from '@angular/common/http';
import { Observable } from 'rxjs';

@Injectable()
export class AuthInterceptor implements HttpInterceptor {

  intercept(req: HttpRequest<any>, next: HttpHandler): Observable<HttpEvent<any>> {
    // Get JWT token from localStorage (set by Clienta app or test token)
    const token = localStorage.getItem('jwt_token');

    // Debug logging
    console.log('🔍 Interceptor - Request URL:', req.url);
    console.log('🔍 Interceptor - Token exists:', !!token);
    console.log('🔍 Interceptor - Needs auth:', this.needsAuth(req.url));

    // Only add Authorization header for API calls that need authentication
    if (token && this.needsAuth(req.url)) {
      console.log('✅ Adding Authorization header to request');
      console.log('🔑 Token (first 50 chars):', token.substring(0, 50) + '...');

      const authReq = req.clone({
        headers: req.headers.set('Authorization', `Bearer ${token}`)
      });

      console.log('📤 Request headers:', authReq.headers.keys());
      return next.handle(authReq);
    }

    console.log('❌ No auth header added');
    return next.handle(req);
  }

  private needsAuth(url: string): boolean {
    console.log('🔍 Checking URL:', url);

    // Simplified logic: Add auth to all backend requests except public ones
    const publicEndpoints = [
      '/api/health/ping',
      '/api/health/test-token'
    ];

    // Check if this is a backend API request
    const isBackendRequest = url.includes('localhost:8080/api/health') || url.includes('/api/health');
    console.log('🔍 Is backend request:', isBackendRequest);

    if (!isBackendRequest) {
      console.log('🔍 Not a backend request, no auth needed');
      return false;
    }

    // Check if it's a public endpoint
    const isPublic = publicEndpoints.some(endpoint => url.includes(endpoint));
    console.log('🔍 Is public endpoint:', isPublic);
    console.log('🔍 Public endpoints:', publicEndpoints);

    const needsAuth = !isPublic;
    console.log('🔍 URL needs auth:', needsAuth);

    return needsAuth;
  }
}
